class Solution {
public:
    int minimumBeautifulSubstrings(string s) {
        unordered_set<string> pows;
        for (long long v = 1; __builtin_popcountll(v) <= 64 && v < (1LL << 15); v *= 5) {
            string b; for (long long x = v; x; x >>= 1) b += char('0' + x % 2);
            reverse(b.begin(), b.end()); pows.insert(b);
        }
        int n = s.size(); const int INF = 1e9;
        vector<int> dp(n + 1, INF); dp[0] = 0;
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                if (dp[j] < INF && s[j] == '1' && pows.count(s.substr(j, i - j)))
                    dp[i] = min(dp[i], dp[j] + 1);
        return dp[n] >= INF ? -1 : dp[n];
    }
};

