class Solution {
    public int minimumBeautifulSubstrings(String s) {
        Set<String> pows = new HashSet<>();
        for (long v = 1; v < (1L << 15); v *= 5) {
            StringBuilder b = new StringBuilder();
            for (long x = v; x > 0; x >>= 1) b.append(x % 2);
            pows.add(b.reverse().toString());
        }
        int n = s.length(), INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[n + 1]; java.util.Arrays.fill(dp, INF); dp[0] = 0;
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                if (dp[j] < INF && s.charAt(j) == '1' && pows.contains(s.substring(j, i)))
                    dp[i] = Math.min(dp[i], dp[j] + 1);
        return dp[n] >= INF ? -1 : dp[n];
    }
}

