from functools import lru_cache
class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        pows = set()
        v = 1
        while v.bit_length() <= 15:
            pows.add(bin(v)[2:]); v *= 5
        n = len(s)
        @lru_cache(None)
        def solve(i):
            if i == n: return 0
            if s[i] == '0': return float('inf')
            best = float('inf')
            for j in range(i + 1, n + 1):
                if s[i:j] in pows:
                    best = min(best, 1 + solve(j))
            return best
        r = solve(0)
        return -1 if r == float('inf') else r

